SELECT COUNT(*) FROM Fires WHERE STATE = 'AK' AND FIRE_YEAR = 1993;
SELECT COUNT(*) FROM Fires WHERE STATE = 'AK' AND FIRE_YEAR = 1993 AND NWCG_CAUSE_CLASSIFICATION = 'Human';
SELECT (CAST(human_count AS REAL) / total_count) * 100 AS percentage FROM (SELECT COUNT(*) AS human_count FROM Fires WHERE STATE = 'AK' AND FIRE_YEAR = 1993 AND NWCG_CAUSE_CLASSIFICATION = 'Human') CROSS JOIN (SELECT COUNT(*) AS total_count FROM Fires WHERE STATE = 'AK' AND FIRE_YEAR = 1993);
SELECT ROUND((CAST(human_count AS REAL) / total_count) * 100, 2) AS percentage FROM (SELECT COUNT(*) AS human_count FROM Fires WHERE STATE = 'AK' AND FIRE_YEAR = 1993 AND NWCG_CAUSE_CLASSIFICATION = 'Human') CROSS JOIN (SELECT COUNT(*) AS total_count FROM Fires WHERE STATE = 'AK' AND FIRE_YEAR = 1993);
